//! Parity tests: the Rust port must reproduce the legacy Python outputs recorded in
//! `parity/golden/*.jsonl` (generated by `parity/gen_golden.py` from the legacy code).
//!
//! Floats are compared bit-for-bit (`to_bits`), not with a tolerance: a one-ULP difference in
//! `ease` would eventually move a card's due date.

use std::fs;
use std::path::PathBuf;

use belajar_core::numeric::{py_round, py_round_ndigits};
use belajar_core::spaced_repetition::{CardState, sm2};
use chrono::NaiveDate;
use serde::Deserialize;

fn golden(name: &str) -> Vec<String> {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "..",
        "..",
        "parity",
        "golden",
        name,
    ]
    .iter()
    .collect();
    let text = fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "cannot read {}: {e}. Run `python parity/gen_golden.py`.",
            path.display()
        )
    });
    text.lines()
        .filter(|l| !l.trim().is_empty())
        .map(str::to_owned)
        .collect()
}

#[derive(Deserialize)]
struct RoundCase {
    op: String,
    x: f64,
    #[serde(default)]
    n: u32,
    out: serde_json::Value,
}

#[test]
fn py_round_matches_python_on_every_golden_case() {
    let lines = golden("py_round.jsonl");
    assert!(
        lines.len() > 10_000,
        "golden corpus unexpectedly small: {}",
        lines.len()
    );

    let (mut plain, mut ndigits) = (0usize, 0usize);
    for line in &lines {
        let case: RoundCase = serde_json::from_str(line).expect("valid golden line");
        match case.op.as_str() {
            "round" => {
                let want = case.out.as_i64().expect("round() returns an int");
                assert_eq!(py_round(case.x), want, "round({:?})", case.x);
                plain += 1;
            }
            "round_nd" => {
                let want = case.out.as_f64().expect("round(x, n) returns a float");
                let got = py_round_ndigits(case.x, case.n);
                assert_eq!(
                    got.to_bits(),
                    want.to_bits(),
                    "round({:?}, {}) = {got:?}, Python says {want:?}",
                    case.x,
                    case.n
                );
                ndigits += 1;
            }
            other => panic!("unknown golden op {other}"),
        }
    }
    assert!(
        plain > 5_000 && ndigits > 5_000,
        "plain={plain} ndigits={ndigits}"
    );
}

/// Guards the guard: the corpus must really contain inputs where `f64::round` and Python disagree,
/// otherwise the test above would pass for a naive implementation too.
#[test]
#[allow(clippy::disallowed_methods)] // deliberately uses f64::round to prove the corpus catches it
fn corpus_distinguishes_python_rounding_from_f64_round() {
    let mut differing = 0usize;
    for line in golden("py_round.jsonl") {
        let case: RoundCase = serde_json::from_str(&line).expect("valid golden line");
        if case.op == "round" {
            let want = case.out.as_i64().expect("int");
            if (case.x.round() as i64) != want {
                differing += 1;
            }
        }
    }
    assert!(
        differing >= 150,
        "only {differing} golden cases separate Python round() from f64::round"
    );
}

#[derive(Deserialize)]
struct CardIn {
    ease: f64,
    interval: i64,
    reps: i64,
    lapses: i64,
}

#[derive(Deserialize)]
struct CardOut {
    ease: f64,
    interval: i64,
    reps: i64,
    lapses: i64,
    due_day: String,
}

#[derive(Deserialize)]
struct Sm2Case {
    card: CardIn,
    grade: i64,
    today: String,
    out: CardOut,
}

#[test]
fn sm2_matches_python_on_every_golden_case() {
    let lines = golden("sm2.jsonl");
    assert!(
        lines.len() > 4_000,
        "golden corpus unexpectedly small: {}",
        lines.len()
    );

    for line in &lines {
        let case: Sm2Case = serde_json::from_str(line).expect("valid golden line");
        let today: NaiveDate = case.today.parse().expect("ISO date");
        let got = sm2(
            CardState {
                ease: case.card.ease,
                interval: case.card.interval,
                reps: case.card.reps,
                lapses: case.card.lapses,
            },
            case.grade,
            today,
        );
        let ctx = format!(
            "card(ease={}, interval={}, reps={}, lapses={}) grade={} today={}",
            case.card.ease,
            case.card.interval,
            case.card.reps,
            case.card.lapses,
            case.grade,
            case.today
        );
        assert_eq!(
            got.state.ease.to_bits(),
            case.out.ease.to_bits(),
            "ease: {ctx}"
        );
        assert_eq!(got.state.interval, case.out.interval, "interval: {ctx}");
        assert_eq!(got.state.reps, case.out.reps, "reps: {ctx}");
        assert_eq!(got.state.lapses, case.out.lapses, "lapses: {ctx}");
        assert_eq!(got.due_day.to_string(), case.out.due_day, "due_day: {ctx}");
    }
}

// ------------------------------------------------------------------------------------------------
// stats.py: streaks, heatmap, weekly totals, study days
// ------------------------------------------------------------------------------------------------

use std::collections::BTreeMap;

use belajar_core::profile::level_info;
use belajar_core::stats::{self, DayTotals, Totals};
use chrono_tz::Tz;
use serde_json::{Value, to_value};

fn totals_from(value: &Value) -> Totals {
    let map: BTreeMap<String, DayTotals> =
        serde_json::from_value(value.clone()).expect("totals object");
    map.into_iter()
        .map(|(day, t)| (day.parse().expect("ISO day"), t))
        .collect()
}

#[test]
fn stats_match_python_on_every_golden_history() {
    let lines = golden("stats.jsonl");
    assert!(
        lines.len() >= 150,
        "golden corpus unexpectedly small: {}",
        lines.len()
    );

    let mut with_freeze_used = 0;
    let mut with_streak = 0;
    for line in &lines {
        let case: Value = serde_json::from_str(line).expect("valid golden line");
        let today: NaiveDate = case["today"]
            .as_str()
            .expect("today")
            .parse()
            .expect("ISO date");
        let goal = case["goal"].as_i64().expect("goal");
        let weekly_setting = case["weekly_setting"].as_str().expect("setting");
        let totals = totals_from(&case["totals"]);
        let ctx = format!("today={today} goal={goal} weekly_setting={weekly_setting:?}");

        let info = stats::streak_info(&totals, goal, today);
        assert_eq!(
            to_value(&info).unwrap(),
            case["streak_info"],
            "streak_info: {ctx}"
        );
        assert_eq!(
            to_value(stats::heatmap(&totals, goal, today, 60)).unwrap(),
            case["heatmap"],
            "heatmap: {ctx}"
        );
        assert_eq!(
            to_value(stats::weekly(&totals, today, Some(weekly_setting))).unwrap(),
            case["weekly"],
            "weekly: {ctx}"
        );
        assert_eq!(
            to_value(stats::study_days(&totals, today, 14)).unwrap(),
            case["study_days"],
            "study_days: {ctx}"
        );
        if !info.streak.freeze_used.is_empty() {
            with_freeze_used += 1;
        }
        if info.streak.current > 0 {
            with_streak += 1;
        }
    }
    // Guard: the corpus really exercises streaks and freezes (otherwise it proves little).
    assert!(
        with_streak >= 20,
        "only {with_streak} cases have a live streak"
    );
    assert!(
        with_freeze_used >= 5,
        "only {with_freeze_used} cases consume a freeze"
    );
}

#[test]
fn day_of_matches_python_across_time_zones_and_dst() {
    let lines = golden("day_of.jsonl");
    assert!(
        lines.len() > 8_000,
        "golden corpus unexpectedly small: {}",
        lines.len()
    );
    for line in &lines {
        let case: Value = serde_json::from_str(line).expect("valid golden line");
        let zone: Tz = case["zone"]
            .as_str()
            .expect("zone")
            .parse()
            .expect("known zone");
        let got = stats::day_of(
            case["ts"].as_f64().expect("ts"),
            zone,
            case["start_hour"].as_i64().expect("start_hour"),
        );
        assert_eq!(
            got.to_string(),
            case["day"].as_str().expect("day"),
            "{line}"
        );
    }
}

#[test]
fn level_info_matches_python() {
    let lines = golden("level.jsonl");
    assert!(
        lines.len() > 3_000,
        "golden corpus unexpectedly small: {}",
        lines.len()
    );
    for line in &lines {
        let case: Value = serde_json::from_str(line).expect("valid golden line");
        let xp = case["xp"].as_i64().expect("xp");
        assert_eq!(to_value(level_info(xp)).unwrap(), case["out"], "xp={xp}");
    }
}

// ------------------------------------------------------------------------------------------------
// difflib.SequenceMatcher, _norm, grade_short_local, _fuzzy_fallback
// ------------------------------------------------------------------------------------------------

use belajar_core::{difflib, grading};

#[test]
fn grading_matches_python_on_every_golden_case() {
    let lines = golden("grading.jsonl");
    assert!(
        lines.len() > 6_000,
        "golden corpus unexpectedly small: {}",
        lines.len()
    );

    let (mut ratios, mut norms, mut grades) = (0, 0, 0);
    let (mut yes, mut no, mut maybe) = (0, 0, 0);
    let mut long_ratio = 0;
    for line in &lines {
        let case: Value = serde_json::from_str(line).expect("valid golden line");
        match case["op"].as_str().expect("op") {
            "ratio" => {
                let (a, b) = (case["a"].as_str().unwrap(), case["b"].as_str().unwrap());
                let want = case["out"].as_f64().unwrap();
                let got = difflib::ratio(a, b);
                assert_eq!(
                    got.to_bits(),
                    want.to_bits(),
                    "ratio({a:?}, {b:?}) = {got}, Python says {want}"
                );
                ratios += 1;
                if b.chars().count() >= 200 {
                    long_ratio += 1;
                }
            }
            "norm" => {
                let text = case["text"].as_str().unwrap();
                assert_eq!(
                    grading::norm(text),
                    case["out"].as_str().unwrap(),
                    "norm({text:?})"
                );
                norms += 1;
            }
            "grade" => {
                let given = case["given"].as_str().unwrap();
                let answer = case["answer"].as_str().unwrap();
                let keywords: Vec<String> = case["keywords"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|k| k.as_str().unwrap().to_owned())
                    .collect();
                let want = case["out"].as_bool();
                let ctx = format!("given={given:?} answer={answer:?} keywords={keywords:?}");
                let got = grading::grade_short_local(given, answer, &keywords);
                assert_eq!(got, want, "grade_short_local: {ctx}");
                assert_eq!(
                    grading::fuzzy_fallback(given, answer, &keywords),
                    case["fuzzy"].as_bool().unwrap(),
                    "fuzzy_fallback: {ctx}"
                );
                grades += 1;
                match got {
                    Some(true) => yes += 1,
                    Some(false) => no += 1,
                    None => maybe += 1,
                }
            }
            other => panic!("unknown op {other}"),
        }
    }
    assert!(
        ratios > 2_500 && norms >= 600 && grades >= 3_000,
        "ratios={ratios} norms={norms} grades={grades}"
    );
    // The corpus must reach every branch, including the autojunk path for 200+ character strings.
    assert!(
        yes > 500 && no > 200 && maybe > 100,
        "verdict mix yes={yes} no={no} maybe={maybe}"
    );
    assert!(
        long_ratio >= 300,
        "only {long_ratio} ratio cases exercise autojunk"
    );
}

// ------------------------------------------------------------------------------------------------
// play_director.mastery_level, cards_export

#[test]
fn mastery_level_matches_python_on_every_golden_case() {
    use belajar_core::mastery::mastery_level;

    let lines = golden("mastery_level.jsonl");
    assert!(
        lines.len() >= 600,
        "golden corpus unexpectedly small: {}",
        lines.len()
    );
    let mut seen = std::collections::BTreeSet::new();
    for line in &lines {
        let case: Value = serde_json::from_str(line).expect("valid golden line");
        let kinds: Vec<String> = case["kinds"]
            .as_array()
            .map(|a| {
                a.iter()
                    .map(|k| k.as_str().expect("kind").to_owned())
                    .collect()
            })
            .unwrap_or_default();
        let got = mastery_level(
            case["score"].as_f64().expect("score"),
            case["n"].as_i64().expect("n"),
            &kinds,
        )
        .as_str();
        assert_eq!(got, case["out"].as_str().unwrap(), "{case}");
        seen.insert(got);
    }
    assert_eq!(
        seen.len(),
        4,
        "the corpus must reach every level, got {seen:?}"
    );
}

#[test]
fn cards_export_matches_python_on_the_real_legacy_code() {
    use belajar_core::cards::{ExportRow, export_text};

    let lines = golden("cards_export.jsonl");
    assert!(lines.len() >= 4, "only {} scenarios", lines.len());
    for line in &lines {
        let case: Value = serde_json::from_str(line).expect("valid golden line");
        let rows: Vec<ExportRow> = case["cards"]
            .as_array()
            .expect("cards")
            .iter()
            .map(|c| ExportRow {
                front: c["front"].as_str().unwrap().to_owned(),
                back: c["back"].as_str().unwrap().to_owned(),
                title: c["title"].as_str().unwrap().to_owned(),
            })
            .collect();
        assert_eq!(
            export_text(&rows),
            case["out"]["text"].as_str().unwrap(),
            "{case}"
        );
        assert_eq!(rows.len() as i64, case["out"]["count"].as_i64().unwrap());
    }
}
